mapper.select:
SELECT

FROM workbench_prompt_kv k
JOIN workbench_prompts p ON p.uuid = k.prompt_ref_uuid
WHERE k.organization_uuid = #{organizationUUID}
AND p.prompt_uuid = #{promptUUID}
AND k.key = #{key}
LIMIT 1

mapper.delete:
DELETE FROM workbench_prompt_kv k
USING workbench_prompts p
WHERE p.uuid = k.prompt_ref_uuid
AND k.organization_uuid = #{organizationUUID}
AND p.prompt_uuid = #{promptUUID}
AND k.key = #{key}
